public class OnClickDetector extends Detector implements XmlScanner, SourceCodeScanner {
    private static final String ANDROID_ON_CLICK = "onClick";
    private static final String ANDROID_NS = "http://schemas.android.com/apk/res/android";

    private final Map<String, List<Attr>> mReferences = new HashMap<>();
    private final Set<String> mHandlers = new HashSet<>();

    @Override
    public Collection<String> getApplicableAttributes() {
        return Collections.singletonList(ANDROID_ON_CLICK);
    }

    @Override
    public void visitAttribute(@NonNull XmlContext context, @NonNull Attr attribute) {
        String value = attribute.getValue();
        if (value == null || value.isEmpty()) {
            return;
        }
        mReferences.computeIfAbsent(value, k -> new ArrayList<>()).add(attribute);
    }

    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UMethod.class);
    }

    @Override
    public UElementHandler createUastHandler(@NonNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitMethod(@NonNull UMethod node) {
                if (node.isPublic() && isValidOnClickMethod(context, node)) {
                    mHandlers.add(node.getName());
                }
            }
        };
    }

    private boolean isValidOnClickMethod(JavaContext context, UMethod method) {
        // Check return type is void
        // Check exactly one parameter of type android.view.View
    }

    @Override
    public void afterCheckRootProject(@NonNull Context context) {
        for (Map.Entry<String, List<Attr>> entry : mReferences.entrySet()) {
            String name = entry.getKey();
            if (!mHandlers.contains(name)) {
                for (Attr attr : entry.getValue()) {
                    // report issue
                }
            }
        }
    }
}
```

